def cite(url,title,file,line):
 r=subprocess.run([sys.executable,str(S),'--ledger',str(ledger),'add',url,'--title',title],capture_output=True,text=True,check=True)
 sid=int(re.search(r'\[(\d+)\]',r.stdout).group(1)); text=(ROOT/'sources'/file).read_text(encoding='utf8').splitlines()[line-1]
 subprocess.run([sys.executable,str(S),'--ledger',str(ledger),'quote',str(sid),'--text',text,'--from',str(ROOT/'sources'/file)],capture_output=True,text=True,check=True)
 return {'citation_id':sid,'url':url,'quote':text,'locator':f'{file}:line {line}','retrieved_date':'2026-10-30','evidence_class':'PRIMARY_SOURCE_AUTHOR_CLAIM'}
